}



import { NextResponse } from 'next/server';
import { dbConnect } from '@/lib/dbConnect';
import Placement from '@/models/Placement';

export async function POST(req: Request) {
  try {
    await dbConnect();
    const body = await req.json();

    // Create new record
    const newPlacement = await Placement.create(body);

    return NextResponse.json({ success: true, data: newPlacement });
  } catch (error) {
    return NextResponse.json({ success: false, error: "Failed to save entry" }, { status: 400 });
  }
}



import { NextRequest, NextResponse } from 'next/server';
import { dbConnect } from '@/lib/dbConnect';
import TrafficLog from '@/models/TrafficLog';

export async function POST(req: NextRequest) {
  try {
    await dbConnect();
    const body = await req.json();

    // Data Eng: Safely extract client IP behind proxies
    const forwardedFor = req.headers.get('x-forwarded-for');
    const ip = forwardedFor ? forwardedFor.split(',')[0].trim() : '127.0.0.1';

    // Leverage Edge Geo-headers
    const country = req.headers.get('x-vercel-ip-country') || 'Unknown';
    const region = req.headers.get('x-vercel-ip-country-region') || 'Unknown';
    const city = req.headers.get('x-vercel-ip-city') || 'Unknown';
    const userAgent = req.headers.get('user-agent') || 'Unknown';

    await TrafficLog.create({
      ip,
      country,
      region,
      city: decodeURIComponent(city),
      path: body.path || '/',
      userAgent,
      duration: body.duration || 0,
    });

    return NextResponse.json({ telemetry: 'Acknowledged' });
  } catch (error) {
    // Non-blocking failure to prevent UI degradation
    console.error("Telemetry Pipeline Error:", error);
    return NextResponse.json({ telemetry: 'Dropped' }, { status: 500 });
  }
}



