export default function PublicDashboardAnalytics({
  placements,
}: {
  placements: any[];
}) {
  const [activeBranch, setActiveBranch] = useState(null);

  const uniqueBranches = useMemo(
    () => Array.from(new Set(placements.map((p) => p.branch).filter(Boolean))),
    [placements],
  );

  const filteredPlacements = useMemo(() => {
    if (!activeBranch) return placements;
    return placements.filter((p) => p.branch === activeBranch);
  }, [placements, activeBranch]);

  // Robust Momentum Logic using your Date Parser
  const momentumData = useMemo(() => {
    const parseDate = (val: string | number) => {
      if (!val) return null;
      const str = String(val).trim();
      if (/^\d{4,5}$/.test(str))
        return new Date((parseInt(str) - 25569) * 86400 * 1000);
      if (str.includes("-") || str.includes("/")) {
        const sep = str.includes("-") ? "-" : "/";
        const parts = str.split(sep);
        if (parts.length === 3) {
          if (parts[2].length === 4)
            return new Date(`${parts[2]}-${parts[1]}-${parts[0]}`);
          if (parts[0].length === 4)
            return new Date(`${parts[0]}-${parts[1]}-${parts[2]}`);
        }
      }
      const fallback = new Date(str);
      return isNaN(fallback.getTime()) ? null : fallback;
    };

    const sorted = [...filteredPlacements]
      .filter((p) => p.date && parseDate(p.date))
      .sort(
        (a, b) =>
          (parseDate(a.date)?.getTime() || 0) -
          (parseDate(b.date)?.getTime() || 0),
      );

    const grouped: Record = {};
    sorted.forEach((p) => {
      const d = parseDate(p.date);
      if (!d) return;
      const key =
        d.toLocaleString("default", { month: "short" }) +
        " '" +
        d.getFullYear().toString().slice(2);
      grouped[key] = (grouped[key] || 0) + 1;
    });

    let cumulative = 0;
    return Object.keys(grouped).map((key) => {
      cumulative += grouped[key];
      return { name: key, cumulative };
    });
  }, [filteredPlacements]);

  const branchCountData = useMemo(() => {
    return uniqueBranches.map((b) => ({
      name: b.length > 10 ? b.substring(0, 8) + "..." : b,
      count: filteredPlacements.filter((p) => p.branch === b).length,
    }));
  }, [filteredPlacements, uniqueBranches]);

  return (


      {/* Pill Filters */}


         setActiveBranch(null)}
          className={`px-6 py-2 rounded-full text-xs font-black uppercase tracking-wider transition-all ${!activeBranch ? "bg-blue-600 text-white shadow-lg" : "text-slate-500"}`}
        >
          Global

        {uniqueBranches.map((branch) => (
           setActiveBranch(branch)}
            className={`px-6 py-2 rounded-full text-xs font-black uppercase tracking-wider transition-all ${activeBranch === branch ? "bg-blue-600 text-white shadow-lg" : "text-slate-500"}`}
          >
            {branch}

        ))}




        {/* Momentum Chart */}




             Placement Momentum












        {/* Branch Count Chart */}




             Branch Wise Count















   acc + (curr.ctc || 0), 0) / (filteredPlacements.length || 1)).toFixed(1)} 
    suffix="LPA" 
    icon={TrendingUp} 
    color="text-indigo-500" 
  />
   0 ? Math.max(...filteredPlacements.map(d => d.ctc || 0)) : 0} 
    suffix="LPA" 
    icon={Award} 
    color="text-amber-500" 
  />
   d.company)).size} 
    icon={Briefcase} 
    color="text-pink-500" 
