"use client";
import { useEffect, useRef } from "react";
import { usePathname } from "next/navigation";

export default function TrafficTracker() {
  const pathname = usePathname();
  const startTime = useRef(0);

  useEffect(() => {
    startTime.current = Date.now();

    const logSessionDuration = () => {
      const currentDuration = Math.round((Date.now() - startTime.current) / 1000);
      if (currentDuration > 2) {
        // sendBeacon is asynchronous and non-blocking during page unloads
        navigator.sendBeacon(
          "/api/traffic",
          JSON.stringify({ path: pathname, duration: currentDuration })
        );
      }
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === "hidden") {
        logSessionDuration();
      } else {
        startTime.current = Date.now();
      }
    };

    window.addEventListener("beforeunload", logSessionDuration);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      logSessionDuration();
      window.removeEventListener("beforeunload", logSessionDuration);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [pathname]);

  return null; // Invisible component
}



import mongoose from 'mongoose';

const TrafficLogSchema = new mongoose.Schema({
  ip: { type: String, required: true, index: true },
  country: { type: String, default: "Unknown" },
  region: { type: String, default: "Unknown" },
  city: { type: String, default: "Unknown" },
  path: { type: String, required: true },
  userAgent: { type: String, default: "Unknown" },
  duration: { type: Number, default: 0 }, // Session duration in seconds
  timestamp: { type: Date, default: Date.now, index: true }
});

// TTL Index to automatically clean logs after 90 days to prevent DB bloat
TrafficLogSchema.index({ timestamp: 1 }, { expireAfterSeconds: 7776000 });

export default mongoose.models.TrafficLog || mongoose.model('TrafficLog', TrafficLogSchema);



