@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* Supreme Palette Extensions */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-border: var(--border);
  --color-ring: var(--ring);

  /* Radius Scale */
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-3xl: 2rem;
}

:root {
  /* Light Mode: Clean "Enterprise White" with Indigo Accents */
  --background: oklch(0.98 0.01 240);
  --foreground: oklch(0.25 0.04 240);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.25 0.04 240);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.25 0.04 240);
  --primary: oklch(0.55 0.20 260); /* Electric Indigo */
  --primary-foreground: oklch(0.98 0.01 240);
  --secondary: oklch(0.92 0.02 240);
  --secondary-foreground: oklch(0.25 0.04 240);
  --muted: oklch(0.92 0.02 240);
  --muted-foreground: oklch(0.5 0.05 240);
  --accent: oklch(0.92 0.02 240);
  --accent-foreground: oklch(0.55 0.20 260);
  --destructive: oklch(0.6 0.18 25);
  --border: oklch(0.9 0.02 240);
  --input: oklch(0.9 0.02 240);
  --ring: oklch(0.55 0.20 260);

  --radius: 1rem;
}

.dark {
  /* Dark Mode: "Deep Space Navy" - High legibility, no more muddy greys */
  --background: oklch(0.12 0.03 240); /* Deep Navy Foundation */
  --foreground: oklch(0.95 0.01 240);
  --card: oklch(0.18 0.04 240 / 0.8); /* Translucent Glass */
  --card-foreground: oklch(0.95 0.01 240);
  --popover: oklch(0.15 0.04 240);
  --popover-foreground: oklch(0.95 0.01 240);
  --primary: oklch(0.65 0.24 260); /* Vivid Indigo */
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.25 0.05 240);
  --secondary-foreground: oklch(0.95 0.01 240);
  --muted: oklch(0.22 0.04 240);
  --muted-foreground: oklch(0.7 0.03 240);
  --accent: oklch(0.28 0.06 240);
  --accent-foreground: oklch(0.65 0.24 260);
  --destructive: oklch(0.5 0.2 25);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.65 0.24 260);
}

@layer base {
  * {
    @apply border-border transition-colors duration-200;
  }
  body {
    @apply bg-background text-foreground antialiased selection:bg-primary/30;
    /* Supreme Background Gradient - Dark Mode Only */
    background-image: var(--bg-gradient);
    background-attachment: fixed;
  }
}

:root {
  --bg-gradient: radial-gradient(at 0% 0%, oklch(0.95 0.02 240) 0px, transparent 50%),
                 radial-gradient(at 100% 100%, oklch(0.92 0.05 260 / 0.1) 0px, transparent 50%);
}

.dark {
  --bg-gradient: radial-gradient(at 0% 0%, oklch(0.18 0.06 250) 0px, transparent 50%),
                 radial-gradient(at 100% 0%, oklch(0.15 0.05 300 / 0.3) 0px, transparent 50%),
                 radial-gradient(at 50% 100%, oklch(0.12 0.04 240) 0px, transparent 50%);
}

/* Custom Scrollbar - Supreme Minimalist */
.custom-scrollbar::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  @apply bg-transparent;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  @apply bg-primary/20 rounded-full hover:bg-primary/50 transition-colors;
}

/* Glassmorphism Utility */
.glass {
  @apply backdrop-blur-xl bg-card border-border;
}
